#hqScreen,#hqScreen :where(*:not(svg,svg *)),#hqScreen :where(*:not(svg,svg *))::before,#hqScreen :where(*:not(svg,svg *))::after{all:revert}
#hqScreen .leaflet-pane,#hqScreen .leaflet-tile,#hqScreen .leaflet-marker-icon,#hqScreen .leaflet-marker-shadow,#hqScreen .leaflet-tile-container,#hqScreen .leaflet-pane > svg,#hqScreen .leaflet-pane > canvas,#hqScreen .leaflet-zoom-box,#hqScreen .leaflet-image-layer,#hqScreen .leaflet-layer{position: absolute; left: 0px; top: 0px;}
#hqScreen .leaflet-tile,#hqScreen .leaflet-marker-icon,#hqScreen .leaflet-marker-shadow{user-select: none; -webkit-user-drag: none;}
#hqScreen .leaflet-tile::selection{background: transparent;}
#hqScreen .leaflet-container .leaflet-overlay-pane svg{max-width: none !important; max-height: none !important;}
#hqScreen .leaflet-container .leaflet-marker-pane img,#hqScreen .leaflet-container .leaflet-shadow-pane img,#hqScreen .leaflet-container .leaflet-tile-pane img,#hqScreen .leaflet-container img.leaflet-image-layer,#hqScreen .leaflet-container .leaflet-tile{width: auto; padding: 0px; max-width: none !important; max-height: none !important;}
#hqScreen .leaflet-container img.leaflet-tile{mix-blend-mode: plus-lighter;}
#hqScreen .leaflet-container.leaflet-touch-zoom{touch-action: pan-x pan-y;}
#hqScreen .leaflet-tile{filter: inherit; visibility: hidden;}
#hqScreen .leaflet-tile-loaded{visibility: inherit;}
#hqScreen .leaflet-overlay-pane svg{}
#hqScreen .leaflet-pane{z-index: 400;}
#hqScreen .leaflet-tile-pane{z-index: 200;}
#hqScreen .leaflet-overlay-pane{z-index: 400;}
#hqScreen .leaflet-shadow-pane{z-index: 500;}
#hqScreen .leaflet-marker-pane{z-index: 600;}
#hqScreen .leaflet-tooltip-pane{z-index: 650;}
#hqScreen .leaflet-popup-pane{z-index: 700;}
#hqScreen .leaflet-map-pane svg{z-index: 200;}
#hqScreen .leaflet-top,#hqScreen .leaflet-bottom{position: absolute; z-index: 1000; pointer-events: none;}
#hqScreen .leaflet-top{top: 0px;}
#hqScreen .leaflet-right{right: 0px;}
#hqScreen .leaflet-bottom{bottom: 0px;}
#hqScreen .leaflet-left{left: 0px;}
#hqScreen .leaflet-zoom-animated{transform-origin: 0px 0px;}
#hqScreen svg.leaflet-zoom-animated{will-change: transform;}
#hqScreen .leaflet-interactive{cursor: pointer;}
#hqScreen .leaflet-popup-pane,#hqScreen .leaflet-control{cursor: auto;}
#hqScreen .leaflet-marker-icon,#hqScreen .leaflet-marker-shadow,#hqScreen .leaflet-image-layer,#hqScreen .leaflet-pane > svg path,#hqScreen .leaflet-tile-container{pointer-events: none;}
#hqScreen .leaflet-marker-icon.leaflet-interactive,#hqScreen .leaflet-image-layer.leaflet-interactive,#hqScreen .leaflet-pane > svg path.leaflet-interactive,#hqScreen svg.leaflet-image-layer.leaflet-interactive path{pointer-events: auto;}
#hqScreen .leaflet-marker-icon,#hqScreen .leaflet-marker-shadow{display: block;}
#hqScreen .leaflet-container.leaflet-touch-drag{touch-action: pinch-zoom;}
#hqScreen .leaflet-container.leaflet-touch-drag.leaflet-touch-zoom{touch-action: none;}
#hqScreen .leaflet-container a{color: rgb(0, 120, 168);}
#hqScreen .leaflet-control{float: left; clear: both;}
#hqScreen .leaflet-right .leaflet-control{margin-right: 10px;}
#hqScreen .leaflet-top .leaflet-control{margin-top: 10px;}
#hqScreen .leaflet-bottom .leaflet-control{margin-bottom: 10px;}
#hqScreen .leaflet-left .leaflet-control{margin-left: 10px;}
#hqScreen .leaflet-grab{cursor: grab;}
#hqScreen .leaflet-bar{box-shadow: rgba(0, 0, 0, 0.65) 0px 1px 5px; border-radius: 4px;}
#hqScreen .leaflet-bar a{background-color: rgb(255, 255, 255); border-bottom: 1px solid rgb(204, 204, 204); width: 26px; height: 26px; line-height: 26px; display: block; text-align: center; text-decoration: none; color: black;}
#hqScreen .leaflet-bar a,#hqScreen .leaflet-control-layers-toggle{background-position: 50% 50%; background-repeat: no-repeat; display: block;}
#hqScreen .leaflet-bar a:first-child{border-top-left-radius: 4px; border-top-right-radius: 4px;}
#hqScreen .leaflet-bar a:last-child{border-bottom-left-radius: 4px; border-bottom-right-radius: 4px; border-bottom: none;}
#hqScreen .leaflet-touch .leaflet-bar a{width: 30px; height: 30px; line-height: 30px;}
#hqScreen .leaflet-touch .leaflet-bar a:first-child{border-top-left-radius: 2px; border-top-right-radius: 2px;}
#hqScreen .leaflet-touch .leaflet-bar a:last-child{border-bottom-left-radius: 2px; border-bottom-right-radius: 2px;}
#hqScreen .leaflet-control-zoom-in,#hqScreen .leaflet-control-zoom-out{font: bold 18px "Lucida Console", Monaco, monospace; text-indent: 1px;}
#hqScreen .leaflet-touch .leaflet-control-zoom-in,#hqScreen .leaflet-touch .leaflet-control-zoom-out{font-size: 22px;}
#hqScreen .leaflet-container .leaflet-control-attribution{background: rgba(255, 255, 255, 0.8); margin: 0px;}
#hqScreen .leaflet-control-attribution,#hqScreen .leaflet-control-scale-line{padding: 0px 5px; color: rgb(51, 51, 51); line-height: 1.4;}
#hqScreen .leaflet-control-attribution a{text-decoration: none;}
#hqScreen .leaflet-attribution-flag{width: 1em; height: 0.6669em; display: inline !important; vertical-align: baseline !important;}
#hqScreen .leaflet-touch .leaflet-control-attribution,#hqScreen .leaflet-touch .leaflet-control-layers,#hqScreen .leaflet-touch .leaflet-bar{box-shadow: none;}
#hqScreen .leaflet-touch .leaflet-control-layers,#hqScreen .leaflet-touch .leaflet-bar{border: 2px solid rgba(0, 0, 0, 0.2); background-clip: padding-box;}
#hqScreen *,#hqScreen ::before,#hqScreen ::after{box-sizing: border-box; min-width: 0px;}
#hqScreen img,#hqScreen picture,#hqScreen video,#hqScreen canvas,#hqScreen svg{max-width: 100%; height: auto; display: block;}
#hqScreen *,#hqScreen ::before,#hqScreen ::after{box-sizing: border-box; margin: 0px; padding: 0px; -webkit-tap-highlight-color: transparent;}
#hqScreen button,#hqScreen .sbtn,#hqScreen .btn,#hqScreen .bnav-item,#hqScreen .nav-tab,#hqScreen .icon-btn{min-height: 44px; touch-action: manipulation;}
#hqScreen [style*="display:flex"][style*="gap:"] > button,#hqScreen [style*="display: flex"][style*="gap:"] > button{min-height: 44px !important;}
#hqScreen .sched-toolbar-row::-webkit-scrollbar{display: none;}
#hqScreen .stats-strip::-webkit-scrollbar{display: none;}
#hqScreen .section::-webkit-scrollbar{width: 4px;}
#hqScreen .section::-webkit-scrollbar-track{background: transparent;}
#hqScreen .section::-webkit-scrollbar-thumb{background: var(--border); border-radius: 4px;}
#hqScreen .sched-toolbar-row::-webkit-scrollbar{display: none;}
#hqScreen *,#hqScreen,#hqScreen{box-sizing: border-box; min-width: 0px;}
#hqScreen{overflow: clip auto; overscroll-behavior-y: contain; text-size-adjust: 100%; max-width: 100%;}
#hqScreen,#hqScreen .pd-body{overflow-x: clip;}
#hqScreen .pd-body{overflow-x: clip; min-height: 762px; margin: 0px; -webkit-tap-highlight-color: transparent; overflow-wrap: anywhere; word-break: break-word;}
#hqScreen svg{max-width: 100%; height: auto; display: block;}
#hqScreen table{width: 100%; max-width: 100%; table-layout: fixed;}
#hqScreen input,#hqScreen select,#hqScreen textarea,#hqScreen button{font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: max(16px, 1em); max-width: 100%;}
#hqScreen #hp_leaflet-map{height: 320px !important;}
#hqScreen *,#hqScreen,#hqScreen{box-sizing: border-box; margin: 0px; padding: 0px; -webkit-tap-highlight-color: transparent;}
#hqScreen{--bg: #07090c; --bg2: #0d1117; --bg3: #111820; --bg4: #161e28; --accent: #c9a96e; --accent2: #a88a52; --accent3: #e0c080; --gold: #c9a96e; --teal: #6dbdd4; --teal2: #4a9bb3; --teal3: #a8d8e8; --red: #e05555; --amber: #d4a04a; --green: #6db974; --green2: #8dd493; --blue: #3d7ab5; --blue2: #6aacf0; --purple: #a060e0; --purple2: #c080f0; --text: #f0ede8; --muted: #a8bfc4; --muted2: rgba(240,237,232,.65); --muted3: rgba(240,237,232,.85); --border: rgba(201,169,110,.12); --border2: rgba(201,169,110,.25); --border3: rgba(201,169,110,.4); --mono: 'DM Mono',monospace; --sans: 'Inter',sans-serif; --safe-bottom: env(safe-area-inset-bottom,0px);}
#hqScreen{height: 100%; background: var(--bg);}
#hqScreen .pd-body{font-family: var(--sans); background: var(--bg); color: var(--text); min-height: 100%; overflow-x: hidden; text-size-adjust: 100%; padding-bottom: calc(64px + var(--safe-bottom));}
#hqScreen button{font-family: var(--sans); cursor: pointer; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: none;}
#hqScreen input,#hqScreen select,#hqScreen textarea{font-family: var(--sans); font-size: 16px;}
#hqScreen a{color: inherit; text-decoration: none;}
#hqScreen #hp_lock{position: fixed; inset: 0px; background: var(--bg); z-index: 999; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 28px; text-align: center; padding: 20px;}
#hqScreen .lock-logo{font-family: var(--serif); font-size: 30px; color: var(--text); font-weight: 300; letter-spacing: 2px; text-align: center; width: 100%; max-width: 320px;}
#hqScreen .lock-sub{font-family: var(--mono); font-size: 12px; letter-spacing: 3px; text-transform: uppercase; color: var(--muted2);}
#hqScreen .lock-dots{display: flex; gap: 14px; justify-content: center;}
#hqScreen .lock-dot{width: 13px; height: 13px; border-radius: 50%; border: 1px solid var(--border2); background: transparent; transition: background 0.15s;}
#hqScreen .lock-pad{display: grid; grid-template-columns: repeat(3, 72px); gap: 10px; margin: 0px auto;}
#hqScreen .lock-key{width: 72px; height: 72px; border-radius: 50%; border: 1px solid var(--border2); background: var(--bg2); color: var(--text); font-size: 22px; font-weight: 300; display: flex; align-items: center; justify-content: center; transition: background 0.12s; user-select: none;}
#hqScreen .lock-key:active{background: var(--bg3); border-color: var(--teal2);}
#hqScreen button{transition: transform 50ms; touch-action: manipulation; -webkit-tap-highlight-color: transparent;}
#hqScreen button:active{transform: scale(0.98);}
#hqScreen .lock-key.del{font-size: 16px; color: var(--muted2);}
#hqScreen .lock-key.empty{background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; pointer-events: none;}
#hqScreen .lock-err{font-family: var(--mono); font-size: 11px; color: var(--red); letter-spacing: 1px; opacity: 0; transition: opacity 0.3s;}
#hqScreen .topbar{position: sticky; top: 0px; z-index: 100; height: 54px; display: flex; align-items: center; justify-content: space-between; padding: 0px 14px; background: rgba(7, 9, 12, 0.96); border-bottom: 1px solid var(--border); backdrop-filter: blur(20px);}
#hqScreen .tl{display: flex; align-items: center; gap: 6px; flex: 1 1 0%; min-width: 0px; overflow: hidden;}
#hqScreen .logo{font-family: var(--serif); font-size: 16px; color: var(--text); font-weight: 300; flex: 0 0 auto; letter-spacing: 1px; white-space: nowrap;}
#hqScreen .logo em{color: var(--teal2); font-style: italic;}
#hqScreen .op-pill{display: flex; align-items: center; gap: 5px; background: var(--bg3); border: 1px solid var(--border2); padding: 4px 8px; border-radius: 100px; cursor: default; min-height: 32px; max-width: 200px; overflow: hidden; flex-shrink: 1;}
#hqScreen .op-live{width: 6px; height: 6px; border-radius: 50%; background: var(--teal2); animation: 2s ease 0s infinite normal none running livepulse;}
@keyframes livepulse { 
  0%, 100% { opacity: 1; box-shadow: rgba(90, 173, 160, 0.4) 0px 0px 0px 0px; }
  50% { opacity: 0.7; box-shadow: rgba(90, 173, 160, 0) 0px 0px 0px 5px; }
}
#hqScreen .op-name-text{font-family: var(--mono); font-size: 12px; letter-spacing: 1px; text-transform: uppercase; color: var(--teal2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 120px;}
#hqScreen .icon-btn{width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; background: var(--bg3); border: 1px solid var(--border); border-radius: 8px; color: var(--muted2); font-size: 17px; cursor: pointer; transition: 0.2s;}
#hqScreen .icon-btn:active{background: var(--bg4); color: var(--teal2);}
@keyframes spin { 
  100% { transform: rotate(360deg); }
}
#hqScreen .stats-strip{display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--border2); border-bottom: 2px solid var(--border); position: sticky; top: 54px; z-index: 90; transition: margin-left 0.2s cubic-bezier(0.4, 0, 0.2, 1);}
#hqScreen .stat-card{background: var(--bg2); padding: 12px 6px; text-align: center;}
#hqScreen .stat-val{font-family: var(--mono); font-size: 22px; font-weight: 700; color: var(--text); line-height: 1; letter-spacing: -0.5px;}
#hqScreen .stat-lbl{font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--muted); margin-top: 4px;}
#hqScreen .crm-board{display: grid; grid-template-columns: repeat(5, 1fr); gap: 1px; background: var(--border); min-height: 400px;}
#hqScreen .crm-col{background: var(--bg2); display: flex; flex-direction: column; min-height: 400px;}
#hqScreen .crm-col-head{padding: 10px 12px; border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; position: sticky; top: 54px; background: var(--bg2); z-index: 2;}
#hqScreen .crm-col-name{font-family: var(--mono); font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--muted2);}
#hqScreen .crm-col-count{font-family: var(--mono); font-size: 11px; color: var(--muted); background: var(--bg3); border: 1px solid var(--border); border-radius: 100px; padding: 1px 6px;}
#hqScreen .crm-col-body{padding: 8px; display: flex; flex-direction: column; gap: 6px; flex: 1 1 0%;}
#hqScreen .crm-chips{display: none; gap: 6px; padding: 8px; overflow-x: auto; background: var(--bg2); border-bottom: 1px solid var(--border); scrollbar-width: none;}
#hqScreen .crm-chip{flex: 0 0 auto; display: inline-flex; align-items: center; gap: 6px; padding: 8px 12px; border: 1px solid var(--border); background: var(--bg3); border-radius: 100px; font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; color: var(--muted2); cursor: pointer; min-height: 40px; touch-action: manipulation; white-space: nowrap;}
#hqScreen .crm-chip.active{border-color: var(--teal2); color: var(--teal2); background: rgba(61, 138, 122, 0.08);}
#hqScreen .crm-chip-count{font-size: 10px; color: var(--muted); background: var(--bg2); border: 1px solid var(--border); border-radius: 100px; padding: 1px 6px;}
#hqScreen .crm-chip.active .crm-chip-count{color: var(--teal2); border-color: rgba(61, 138, 122, 0.3);}
#hqScreen .conflict-modal-overlay{position: fixed; inset: 0px; background: rgba(0, 0, 0, 0.75); z-index: 1500; display: none; align-items: center; justify-content: center; padding: 16px;}
#hqScreen .conflict-modal-box{background: var(--bg2); border: 1px solid var(--red); border-radius: 12px; padding: 20px; max-width: 360px; width: 100%;}
#hqScreen .conflict-modal-title{font-family: var(--mono); font-size: 12px; letter-spacing: 2px; text-transform: uppercase; color: var(--red); margin-bottom: 12px;}
#hqScreen .conflict-modal-reason{font-size: 13px; color: var(--text); margin-bottom: 8px; line-height: 1.5;}
#hqScreen .conflict-modal-sub{font-family: var(--mono); font-size: 12px; color: var(--muted2); margin-bottom: 4px;}
#hqScreen .conflict-modal-btns{display: flex; gap: 8px; margin-top: 16px;}
#hqScreen .conflict-modal-btns button{flex: 1 1 0%; padding: 10px; border-radius: 6px; font-family: var(--mono); font-size: 12px; letter-spacing: 1px; text-transform: uppercase; cursor: pointer; min-height: 44px; border: 1px solid;}
#hqScreen .cm-override-btn{background: rgba(224, 85, 85, 0.1); color: var(--red); border-color: var(--red) !important;}
#hqScreen .cm-cancel-btn{background: var(--bg3); color: var(--muted2); border-color: var(--border2) !important;}
#hqScreen .shift-detail-overlay{position: fixed; inset: 0px; background: rgba(0, 0, 0, 0.75); z-index: 1062; display: none; align-items: center; justify-content: center; padding: 16px;}
#hqScreen .shift-detail-box{background: var(--bg2); border: 1px solid var(--border2); border-radius: 12px; padding: 20px; max-width: 340px; width: 100%;}
#hqScreen .sd-title{font-size: 16px; font-weight: 500; color: var(--text); margin-bottom: 4px;}
#hqScreen .sd-row{font-family: var(--mono); font-size: 11px; color: var(--muted2); margin-bottom: 4px;}
#hqScreen .sd-status{font-family: var(--mono); font-size: 12px; letter-spacing: 1px; margin-bottom: 12px;}
#hqScreen .sd-conflict-row{background: rgba(224, 85, 85, 0.08); border: 1px solid rgba(224, 85, 85, 0.25); border-radius: 6px; padding: 8px 10px; margin-bottom: 12px; font-family: var(--mono); font-size: 12px; color: var(--red); line-height: 1.5;}
#hqScreen .sd-btns{display: flex; gap: 8px;}
#hqScreen .sd-btns button{flex: 1 1 0%; padding: 9px; border-radius: 6px; font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; cursor: pointer; min-height: 44px; border: 1px solid;}
#hqScreen .sd-edit-btn{background: rgba(61, 138, 122, 0.1); color: var(--teal2); border-color: rgba(61, 138, 122, 0.3) !important;}
#hqScreen .sd-delete-btn{background: rgba(224, 85, 85, 0.08); color: var(--red); border-color: rgba(224, 85, 85, 0.2) !important;}
#hqScreen .sd-close-btn{background: var(--bg3); color: var(--muted2); flex: 0.5 1 0%; border-color: var(--border) !important;}
#hqScreen .nav-tabs{display: flex; background: var(--bg2); border-bottom: 1px solid var(--border); overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none;}
#hqScreen .nav-tab{flex-shrink: 0; padding: 11px 14px; font-family: var(--mono); font-size: 12px; letter-spacing: 2px; text-transform: uppercase; color: var(--muted2); border-bottom: 2px solid transparent; cursor: pointer; white-space: nowrap; min-height: 44px; display: flex; align-items: center; gap: 5px; touch-action: manipulation; -webkit-tap-highlight-color: transparent;}
#hqScreen .nav-tab:active{color: var(--teal3);}
#hqScreen .nbadge{background: var(--teal); color: rgb(255, 255, 255); border-radius: 100px; font-size: 11px; min-width: 15px; height: 15px; padding: 0px 3px; display: inline-flex; align-items: center; justify-content: center;}
#hqScreen .section{display: none; padding-top: 16px; padding-bottom: 8px; opacity: 0; transition: opacity 150ms;}
#hqScreen .section.active{display: block; opacity: 1;}
#hqScreen .section.active{display: block;}
#hqScreen .section.visible{opacity: 1;}
#hqScreen .section-header{display: flex; align-items: center; justify-content: space-between; padding: 12px 14px 8px;}
#hqScreen .section-title{font-size: 12px; letter-spacing: 3px; text-transform: uppercase; color: var(--muted2);}
#hqScreen .sect-action{font-family: var(--mono); font-size: 12px; letter-spacing: 1px; text-transform: uppercase; color: var(--teal2); padding: 7px 12px; border: 1px solid var(--border2); border-radius: 4px; cursor: pointer; min-height: 44px; display: flex; align-items: center; touch-action: manipulation; -webkit-tap-highlight-color: transparent; white-space: nowrap; flex-shrink: 0;}
#hqScreen .sect-action:active{background: rgba(61, 138, 122, 0.08); border-color: var(--teal2);}
#hqScreen .card{margin: 0px 12px 8px; background: var(--bg2); border: 1px solid var(--border); border-radius: 10px; overflow: hidden; transition: border-color 0.15s;}
#hqScreen .card[onclick]{cursor: pointer;}
#hqScreen .card[onclick]:active{border-color: var(--border2); background: var(--bg3);}
#hqScreen .card-header{padding: 13px 14px; display: flex; align-items: flex-start; justify-content: space-between; gap: 8px;}
#hqScreen .card-header[onclick]{cursor: pointer;}
#hqScreen .card-name{font-size: 14px; font-weight: 500; color: var(--text);}
#hqScreen .card-sub{font-family: var(--mono); font-size: 11px; color: var(--muted2); margin-top: 3px;}
#hqScreen .card-meta{font-size: 11px; color: var(--muted); margin-top: 3px;}
#hqScreen .card-right{display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex-shrink: 0;}
#hqScreen .card-actions{display: flex; border-top: 1px solid var(--border); padding: 0px; gap: 0px;}
#hqScreen .card-act{flex: 1 1 0%; padding: 11px 6px; text-align: center; font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; color: var(--muted2); border-right: 1px solid var(--border); cursor: pointer; min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 3px; transition: background 0.12s, color 0.12s;}
#hqScreen .card-act:last-child{border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
#hqScreen .card-act:active{background: var(--bg3);}
#hqScreen .card-act.call{color: var(--teal2);}
#hqScreen .card-act.call:active{color: var(--teal3); background: rgba(61, 138, 122, 0.08);}
#hqScreen .card-act.ok{color: var(--green2);}
#hqScreen .card-act.ok:active{color: var(--green2); background: rgba(74, 154, 110, 0.08);}
#hqScreen .badge{font-family: var(--mono); font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; padding: 3px 8px; border-radius: 100px; display: inline-block;}
#hqScreen .b-new{background: rgba(61, 138, 122, 0.15); color: var(--teal2); border: 1px solid rgba(61, 138, 122, 0.3);}
#hqScreen .b-contacted{background: rgba(61, 122, 181, 0.15); color: var(--blue2); border: 1px solid rgba(61, 122, 181, 0.3);}
#hqScreen .b-booked{background: rgba(200, 169, 110, 0.15); color: var(--gold); border: 1px solid rgba(200, 169, 110, 0.3);}
#hqScreen .b-converted{background: rgba(74, 154, 110, 0.15); color: var(--green2); border: 1px solid rgba(74, 154, 110, 0.3);}
#hqScreen .b-dead{background: rgba(80, 80, 80, 0.1); color: rgb(85, 85, 85); border: 1px solid rgba(80, 80, 80, 0.2);}
