#hqScreen .ov-kpi{padding: 12px 10px;}
#hqScreen .ov-kpi-val{font-size: 20px;}
#hqScreen .card{margin-left: 0px; margin-right: 0px; border-radius: 0px; border-left-width: medium; border-left-style: none; border-left-color: currentcolor; border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
#hqScreen .card:first-child{border-top-width: medium; border-top-style: none; border-top-color: currentcolor;}
#hqScreen .sheet{border-radius: 20px 20px 0px 0px;}
#hqScreen .sheet-body{padding: 12px 14px;}
#hqScreen .srow2{grid-template-columns: 1fr;}
#hqScreen .sched-toolbar-row{flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; padding-bottom: 4px;}
#hqScreen .sched-toolbar-row .sect-action{flex-shrink: 0; font-size: 11px; padding: 7px 10px;}
#hqScreen .quick-actions{gap: 6px; padding: 6px 10px;}
#hqScreen .quick-actions button{font-size: 10px; padding: 0px 6px;}
#hqScreen .cos-item-action{font-size: 9px; padding: 4px 8px; min-height: 30px;}
#hqScreen #hp_client-sheet-save-bar,#hqScreen #hp_psw-sheet-save-bar{padding: 8px 12px calc(8px + env(safe-area-inset-bottom));}
#hqScreen .logo{font-size: 14px;}
#hqScreen .op-pill{display: none;}
#hqScreen .bnav-lbl{font-size: 10px; letter-spacing: 0px;}
#hqScreen .kpi-val{font-size: 20px;}
#hqScreen .ov-kpi-val{font-size: 18px;}
#hqScreen .stat-val{font-size: 16px;}
#hqScreen .section-title{font-size: 10px; letter-spacing: 2px;}
#hqScreen .card-name{font-size: 12px;}
#hqScreen .card-act{font-size: 10px; padding: 9px 3px;}
#hqScreen .sect-action{font-size: 10px; padding: 6px 8px;}
#hqScreen .sbtn{font-size: 11px;}
#hqScreen .toast.ok{border-color: var(--teal2); color: var(--teal2);}
#hqScreen .grid-chip{padding: 4px 6px; border-radius: var(--r4); cursor: pointer; transition: 0.12s; border: 1px solid transparent; min-height: 28px; display: flex; flex-direction: column; gap: 1px;}
#hqScreen .grid-chip:active{opacity: 0.75;}
#hqScreen .gc-client{font-size: 11px; font-weight: 500; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 90px;}
#hqScreen .gc-time{font-family: var(--mono); font-size: 10px; color: var(--muted2);}
#hqScreen .gc-scheduled{background: var(--teal-dim); border-color: var(--teal-border);}
#hqScreen .gc-client{max-width: 52px; font-size: 10px;}
#hqScreen .gc-time{font-size: 9px;}
#hqScreen .grid-chip{padding: 3px 4px; min-height: 32px;}
#hqScreen .gc-client{font-size: 10px;}
#hqScreen .grid-chip{padding: 3px 4px;}
#hqScreen img,#hqScreen svg{max-width: 100%; height: auto; display: block;}
#hqScreen .leaflet-container{max-width: 100%; width: 100% !important; height: 100% !important;}
#hqScreen .b-scheduled{background: rgba(61, 138, 122, 0.1); color: var(--teal2);}
#hqScreen .cal-day.has-b{background: var(--bg3);}
#hqScreen .cal-dot{width: 5px; height: 5px; border-radius: 50%; background: var(--teal2);}
#hqScreen .today-shift-row{display: flex; align-items: center; gap: 10px; padding: 10px 14px; border-bottom: 1px solid var(--border);}
#hqScreen .tsr-time{font-family: var(--mono); font-size: 11px; color: var(--teal2); min-width: 44px;}
#hqScreen .tsr-client{font-size: 13px; font-weight: 500; color: var(--text); flex: 1 1 0%;}
#hqScreen .tsr-psw{font-family: var(--mono); font-size: 12px; color: var(--muted2);}
#hqScreen .tsr-status{font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase;}
#hqScreen .tsr-expand{display: none; padding: 10px 14px 12px; border-top: 1px solid var(--border); background: var(--bg3);}
#hqScreen .tsr-action-row{display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap;}
#hqScreen .tsr-act{font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; padding: 8px 14px; border-radius: 6px; border: 1px solid var(--border2); color: var(--teal2); cursor: pointer; min-height: 44px; display: flex; align-items: center; touch-action: manipulation;}
#hqScreen .tsr-act:active{background: rgba(61, 138, 122, 0.1);}
#hqScreen .tsr-act.warn{color: var(--amber); border-color: rgba(224, 154, 61, 0.3);}
#hqScreen .today-shift-row{cursor: pointer;}
#hqScreen .today-shift-row:active{background: var(--bg3);}
#hqScreen .psw-on-shift-bar{display: flex; align-items: center; gap: 8px; padding: 6px 14px; background: rgba(61, 138, 122, 0.06); border-top: 1px solid rgba(61, 138, 122, 0.12);}
#hqScreen .psw-shift-dot{width: 7px; height: 7px; border-radius: 50%; background: var(--green2); animation: 1.5s ease 0s infinite normal none running livepulse; flex-shrink: 0;}
#hqScreen .completion-bar{height: 4px; background: var(--bg3); border-radius: 2px; overflow: hidden; margin-top: 4px;}
#hqScreen .completion-fill{height: 100%; background: var(--teal2); border-radius: 2px; transition: width 0.4s;}
#hqScreen .gc-live{background: var(--green-dim); border-color: var(--green-border); animation: 2s ease 0s infinite normal none running livepulse;}
